public class LoginTest
{
    [Fact]
    public void TestLogin_WithValidCredentials_ShouldSucceed()
    {
        // Arrange
        var username = "as specified";
        var password = "as specified";
        var mockAuthService = new MockAuthService();
        mockAuthService.Setup(a => a.Authenticate(username, password)).Returns(true);

        var loginService = new LoginService(mockAuthService.Object);

        // Act
        var result = loginService.Login(username, password);

        // Assert
        Assert.True(result);
    }

    [Fact]
    public void TestLogin_WithInvalidCredentials_ShouldFail()
    {
        // Arrange
        var username = "as specified";
        var password = "as specified";
        var mockAuthService = new MockAuthService();
        mockAuthService.Setup(a => a.Authenticate(username, password)).Returns(false);

        var loginService = new LoginService(mockAuthService.Object);

        // Act
        var result = loginService.Login(username, password);

        // Assert
        Assert.False(result);
    }
}

